function Marco({ titulo, children }) {
  return <section><h1>{titulo}</h1>{children}</section>;
}

function Fila({ nombre, estado = "pendiente" }) {
  return <li>{nombre}: {estado}</li>;
}

const pedidos = [
  { id: 1, nombre: "Ñandú" },
  { id: 2, nombre: "Lomas", estado: "entregado" },
];

<Marco titulo="Hoy">
  <ul>
    {pedidos.map(p => <Fila key={p.id} nombre={p.nombre} estado={p.estado} />)}
  </ul>
</Marco>
